mapper.select:
SELECT a.aux_code AS auxCode, a.aux_name AS auxName, COUNT(1) AS recordCount, COALESCE(SUM(a.amount), 0) AS totalAmount FROM t_accounting_voucher_auxiliary a WHERE a.aux_type = #{auxType} AND a.is_delete = 0
AND a.accounting_date >= #{startDate}
AND a.accounting_date <= #{endDate}
GROUP BY a.aux_code, a.aux_name ORDER BY totalAmount DESC

SELECT COALESCE(SUM(a.amount), 0) AS totalAmount, COALESCE(SUM(CASE WHEN e.debit_credit = 1 OR (e.debit_credit IS NULL AND a.change_direction = 1) THEN a.amount ELSE 0 END), 0) AS debitAmount, COALESCE(SUM(CASE WHEN e.debit_credit = 2 OR (e.debit_credit IS NULL AND a.change_direction = 2) THEN a.amount ELSE 0 END), 0) AS creditAmount, COUNT(DISTINCT a.aux_code) AS itemCount, COUNT(DISTINCT a.subject_code) AS subjectCount, COUNT(DISTINCT a.voucher_no) AS voucherCount FROM t_accounting_voucher_auxiliary a LEFT JOIN t_accounting_voucher_entry e ON a.entry_id = e.entry_id AND e.is_delete = 0 LEFT JOIN t_account_subject s ON a.subject_code = s.subject_code AND s.is_delete = 0 WHERE a.aux_type = #{auxType} AND a.is_delete = 0
AND a.aux_code = #{auxCode}
AND a.accounting_date >= #{startDate}
AND a.accounting_date <= #{endDate}
AND (a.subject_code = #{subjectCode} OR a.subject_code LIKE CONCAT(#{subjectCode}, '%'))
AND s.subject_category = #{subjectCategory}
AND (a.aux_name LIKE CONCAT('%', #{keyword}, '%') OR a.aux_code LIKE CONCAT('%', #{keyword}, '%') OR a.voucher_no LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%') OR s.subject_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT a.subject_code AS subjectCode, a.aux_code AS auxCode, COALESCE(SUM(a.amount), 0) AS amount FROM t_accounting_voucher_auxiliary a LEFT JOIN t_account_subject s ON a.subject_code = s.subject_code AND s.is_delete = 0 LEFT JOIN t_accounting_voucher_entry e ON a.entry_id = e.entry_id AND e.is_delete = 0 WHERE a.aux_type = #{auxType} AND a.is_delete = 0
AND a.accounting_date >= #{startDate}
AND a.accounting_date <= #{endDate}
AND (a.subject_code = #{subjectCode} OR a.subject_code LIKE CONCAT(#{subjectCode}, '%'))
AND s.subject_category = #{subjectCategory}
AND (a.aux_name LIKE CONCAT('%', #{keyword}, '%') OR a.aux_code LIKE CONCAT('%', #{keyword}, '%') OR a.voucher_no LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%') OR s.subject_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY a.subject_code, a.aux_code ORDER BY a.subject_code ASC

SELECT a.subject_code AS subjectCode, COALESCE(SUM(CASE WHEN e.debit_credit = 1 OR (e.debit_credit IS NULL AND a.change_direction = 1) THEN a.amount ELSE 0 END), 0) AS debitAmount, COALESCE(SUM(CASE WHEN e.debit_credit = 2 OR (e.debit_credit IS NULL AND a.change_direction = 2) THEN a.amount ELSE 0 END), 0) AS creditAmount, COALESCE(SUM(a.amount), 0) AS totalAmount, COUNT(1) AS entryCount FROM t_accounting_voucher_auxiliary a LEFT JOIN t_account_subject s ON a.subject_code = s.subject_code AND s.is_delete = 0 LEFT JOIN t_accounting_voucher_entry e ON a.entry_id = e.entry_id AND e.is_delete = 0 WHERE a.aux_type = #{auxType} AND a.is_delete = 0
AND a.aux_code = #{auxCode}
AND a.accounting_date >= #{startDate}
AND a.accounting_date <= #{endDate}
AND (a.subject_code = #{subjectCode} OR a.subject_code LIKE CONCAT(#{subjectCode}, '%'))
AND s.subject_category = #{subjectCategory}
AND (a.aux_name LIKE CONCAT('%', #{keyword}, '%') OR a.aux_code LIKE CONCAT('%', #{keyword}, '%') OR a.voucher_no LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%') OR s.subject_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY a.subject_code ORDER BY totalAmount DESC

SELECT a.id AS id, a.accounting_date AS accountingDate, a.voucher_no AS voucherNo, a.entry_id AS entryId, COALESCE(e.summary, v.summary) AS summary, a.aux_type AS auxType, a.aux_code AS auxCode, a.aux_name AS auxName, a.subject_code AS subjectCode, s.subject_name AS subjectName, a.change_direction AS changeDirection, e.debit_credit AS debitCredit, a.amount AS amount FROM t_accounting_voucher_auxiliary a LEFT JOIN t_accounting_voucher_entry e ON a.entry_id = e.entry_id AND e.is_delete = 0 LEFT JOIN t_accounting_voucher v ON a.voucher_no = v.voucher_no AND v.is_delete = 0 LEFT JOIN t_account_subject s ON a.subject_code = s.subject_code AND s.is_delete = 0 WHERE a.aux_type = #{auxType} AND a.is_delete = 0
AND a.aux_code = #{auxCode}
AND a.accounting_date >= #{startDate}
AND a.accounting_date <= #{endDate}
AND (a.subject_code = #{subjectCode} OR a.subject_code LIKE CONCAT(#{subjectCode}, '%'))
AND s.subject_category = #{subjectCategory}
AND (a.aux_name LIKE CONCAT('%', #{keyword}, '%') OR a.aux_code LIKE CONCAT('%', #{keyword}, '%') OR a.voucher_no LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%') OR s.subject_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.accounting_date DESC, a.id DESC
